+#ifndef TEST_ROSIDL_BUFFER__TEST_BUFFER_IMPL_HPP_
+#define TEST_ROSIDL_BUFFER__TEST_BUFFER_IMPL_HPP_
+
+#include <atomic>
+#include <cstdint>
+#include <cstring>
+#include <memory>
+#include <stdexcept>
+#include <string>
